def cyclic_tape_update(tape: list[int], mod: int, rounds: int) -> list[int]:
    if not tape or rounds == 0:
        return list(tape)
    n = len(tape)
    for _ in range(rounds):
        new_tape = []
        for i in range(n):
            prev = (i - 1) % n
            next_idx = (i + 1) % n
            current = tape[i]
            new_val = (tape[prev] + tape[next_idx] - current) % mod
            new_tape.append(new_val)
        tape = new_tape
    return tape

def cyclic_tape_update(tape: list[int], mod: int, rounds: int) -> list[int]:
    n = len(tape)
    if n == 0 or rounds == 0:
        return tape.copy()
    for _ in range(rounds):
        new_tape = []
        for i in range(n):
            left = tape[(i - 1) % n]
            right = tape[(i + 1) % n]
